<?php
/** Template Name: لندینگ درب بازکن هوشمند آریا */
declare(strict_types=1);
if (!defined('ABSPATH')) exit;
get_header();
$postId = (int) get_the_ID();
$sections = array_values(array_filter(\ErfanSanat\Theme\Admin\SectionManager\SectionStorage::get($postId), static fn(array $section): bool => !empty($section['enabled'])));
if ($sections === []) $sections = [['id' => 'arya-hero', 'type' => 'arya-hero', 'enabled' => true, 'order' => 0, 'fields' => ['title' => get_the_title($postId), 'body' => (string) get_post_field('post_content', $postId), 'button_text' => 'درخواست مشاوره', 'button_url' => home_url('/contact/')]]];
?>
<main id="primary" class="site-main" data-arya-landing="true">
<nav data-landing-menu="landing" aria-label="فهرست صفحه آریا" class="sticky top-0 z-30 border-b border-slate-200 bg-white/95 px-4 py-3 backdrop-blur"><div class="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-3"><a href="#arya-top" class="font-black text-slate-900">آریا</a><?php if (has_nav_menu('landing')) : wp_nav_menu(['theme_location' => 'landing', 'container' => false, 'menu_class' => 'flex flex-wrap items-center gap-4 text-sm font-bold text-slate-700', 'fallback_cb' => false]); else : ?><ul class="flex flex-wrap items-center gap-4 text-sm font-bold text-slate-700"><?php foreach ($sections as $section) : $sid = sanitize_html_class((string) ($section['id'] ?? $section['type'])); ?><li><a href="#arya-<?php echo esc_attr($sid); ?>" class="hover:text-emerald-700"><?php echo esc_html((string) (($section['fields']['title'] ?? '') ?: $section['type'])); ?></a></li><?php endforeach; ?></ul><?php endif; ?></div></nav>
<div id="arya-top" class="mx-auto max-w-7xl space-y-7 px-4 py-8 sm:px-6 lg:px-8">
<?php foreach ($sections as $index => $section) : $type = sanitize_key((string) ($section['type'] ?? 'arya-section')); $fields = is_array($section['fields'] ?? null) ? $section['fields'] : []; $sid = sanitize_html_class((string) ($section['id'] ?? $type)); $title = trim((string) ($fields['title'] ?? '')); if ($title === '' && $index === 0) $title = get_the_title($postId); $body = (string) ($fields['body'] ?? ''); $items = is_array($fields['items'] ?? null) ? $fields['items'] : []; $image = $fields['image'] ?? ''; if (is_numeric($image) && (int) $image > 0) $image = wp_get_attachment_image_url((int) $image, 'large') ?: ''; $image = is_scalar($image) ? esc_url((string) $image) : ''; ?>
<section id="arya-<?php echo esc_attr($sid); ?>" data-arya-section="<?php echo esc_attr($type); ?>" class="rounded-3xl <?php echo $index === 0 ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'; ?> p-6 md:p-10"><div class="<?php echo $image !== '' && $index === 0 ? 'grid gap-8 md:grid-cols-2 md:items-center' : ''; ?>"><?php if ($image !== '' && $index === 0) : ?><img src="<?php echo esc_url($image); ?>" alt="<?php echo esc_attr($title); ?>" class="order-2 max-h-[440px] w-full rounded-2xl object-contain md:order-1" loading="lazy"><?php endif; ?><div><p class="text-xs font-bold <?php echo $index === 0 ? 'text-emerald-300' : 'text-emerald-700'; ?>">درب بازکن هوشمند آریا</p><?php if ($title !== '') : ?><?php echo $index === 0 ? '<h1 class="mt-3 text-3xl font-black leading-relaxed md:text-5xl">' . esc_html($title) . '</h1>' : '<h2 class="mt-2 text-2xl font-black">' . esc_html($title) . '</h2>'; ?><?php endif; ?><?php if ($body !== '') : ?><div class="mt-4 text-sm leading-8 <?php echo $index === 0 ? 'text-slate-200' : 'text-slate-600'; ?>"><?php echo wp_kses_post($body); ?></div><?php endif; ?>
<?php if ($index === 0) : $buttonText = trim((string) ($fields['button_text'] ?? '')); $buttonUrl = (string) ($fields['button_url'] ?? home_url('/contact/')); if ($buttonText === '') $buttonText = 'دریافت مشاوره'; ?><a href="<?php echo esc_url($buttonUrl); ?>" class="mt-6 inline-flex rounded-xl bg-emerald-600 px-5 py-3 text-sm font-extrabold text-white"><?php echo esc_html($buttonText); ?></a><?php endif; ?></div></div>
<?php if ($items !== []) : ?><ul class="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><?php foreach ($items as $item) : if (is_scalar($item) && trim((string) $item) !== '') : ?><li class="rounded-2xl bg-slate-50 p-4 text-sm font-bold text-slate-700"><?php echo esc_html((string) $item); ?></li><?php elseif (is_array($item)) : ?><li class="rounded-2xl bg-slate-50 p-4"><strong class="text-sm font-bold text-slate-900"><?php echo esc_html((string) ($item['title'] ?? '')); ?></strong><?php if (isset($item['body']) && is_scalar($item['body'])) : ?><p class="mt-2 text-xs leading-6 text-slate-600"><?php echo esc_html((string) $item['body']); ?></p><?php endif; ?></li><?php endif; endforeach; ?></ul><?php endif; ?></section>
<?php endforeach; ?>
</div></main>
<?php get_footer(); ?>
